1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --cell: 28px;
10	    --bg: #14161c;
11	    --panel: #1e2129;
12	    --line: #2a2e38;
13	    --text: #e8eaf0;
14	    --muted: #9aa0ad;
15	  }
16	  * { box-sizing: border-box; }
17	  body {
18	    margin: 0;
19	    min-height: 100vh;
20	    display: flex;
21	    align-items: center;
22	    justify-content: center;
23	    background: var(--bg);
24	    color: var(--text);
25	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
26	  }
27	  .game {
28	    display: flex;
29	    gap: 20px;
30	    align-items: flex-start;
31	    padding: 20px;
32	  }
33	  .board-wrap { position: relative; }
34	  .board {
35	    display: grid;
36	    grid-template-columns: repeat(10, var(--cell));
37	    grid-template-rows: repeat(20, var(--cell));
38	    gap: 1px;
39	    padding: 1px;
40	    background: var(--line);
41	    border: 2px solid var(--line);
42	  }
43	  .cell { background: var(--panel); }
44	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
45	  .overlay {
46	    position: absolute;
47	    inset: 0;
48	    display: flex;
49	    align-items: center;
50	    justify-content: center;
51	    background: rgba(0,0,0,0.6);
52	    font-size: 24px;
53	    font-weight: 600;
54	  }
55	  .side {
56	    display: flex;
57	    flex-direction: column;
58	    gap: 14px;
59	    min-width: 140px;
60	  }
61	  .box {
62	    background: var(--panel);
63	    border: 1px solid var(--line);
64	    padding: 10px 12px;
65	  }
66	  .label {
67	    font-size: 11px;
68	    text-transform: uppercase;
69	    letter-spacing: 0.08em;
70	    color: var(--muted);
71	  }
72	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
73	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
74	  .mini {
75	    display: grid;
76	    grid-template-columns: repeat(4, 16px);
77	    grid-template-rows: repeat(2, 16px);
78	    gap: 1px;
79	  }
80	  .mini-cell { background: transparent; }
81	  button {
82	    font: inherit;
83	    color: var(--text);
84	    background: var(--panel);
85	    border: 1px solid var(--line);
86	    padding: 8px 12px;
87	    cursor: pointer;
88	  }
89	  button:hover { border-color: var(--muted); }
90	  .help { font-size: 12px; color: var(--muted); line-height: 1.6; }
91	  .p-I { background: #22c7e0; }
92	  .p-O { background: #f2c511; }
93	  .p-T { background: #9b4dca; }
94	  .p-S { background: #3cb44b; }
95	  .p-Z { background: #e6194b; }
96	  .p-J { background: #2f6fdf; }
97	  .p-L { background: #f58231; }
98	</style>
99	</head>
100	<body>
101	<div class="game">
102	  <div class="board-wrap">
103	    <div class="board" data-testid="board" id="board"></div>
104	    <div class="overlay" id="overlay" hidden>Game over</div>
105	  </div>
106	  <div class="side">
107	    <div class="box">
108	      <div class="label">Score</div>
109	      <div class="value" data-testid="score" id="score">0</div>
110	    </div>
111	    <div class="box">
112	      <div class="label">Level</div>
113	      <div class="value" data-testid="level" id="level">1</div>
114	    </div>
115	    <div class="box">
116	      <div class="label">Lines</div>
117	      <div class="value" data-testid="lines" id="lines">0</div>
118	    </div>
119	    <div class="box">
120	      <div class="label">Next</div>
121	      <div class="next-list" id="next"></div>
122	    </div>
123	    <button type="button" id="new-game">New game</button>
124	    <div class="help">
125	      ← → move<br>
126	      ↓ soft drop<br>
127	      Space hard drop<br>
128	      ↑ rotate
129	    </div>
130	  </div>
131	</div>
132	
133	<script>
134	(function () {
135	  "use strict";
136	
137	  var ROWS = 20;
138	  var COLS = 10;
139	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
140	  var PREVIEW = 3;
141	  var GRAVITY_MS = 1000;
142	
143	  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
144	  var SHAPES = {
145	    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
146	    O: { m: ["OO", "OO"], row: 0, col: 4 },
147	    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
148	    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
149	    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
150	    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
151	    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
152	  };
153	
154	  // ---- State ----
155	  var board;        // board[row][col] = "" or piece letter
156	  var current;      // { type, matrix, row, col } or null
157	  var next;         // upcoming piece letters, soonest first
158	  var scripted;     // true while `next` comes from a test-supplied queue
159	  var bag = [];
160	  var score, level, lines, status;
161	  var timer = null;
162	
163	  function emptyBoard() {
164	    var b = [];
165	    for (var r = 0; r < ROWS; r++) {
166	      var row = [];
167	      for (var c = 0; c < COLS; c++) row.push("");
168	      b.push(row);
169	    }
170	    return b;
171	  }
172	
173	  function randomType() {
174	    if (bag.length === 0) {
175	      bag = TYPES.slice();
176	      for (var i = bag.length - 1; i > 0; i--) {
177	        var j = Math.floor(Math.random() * (i + 1));
178	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
179	      }
180	    }
181	    return bag.pop();
182	  }
183	
184	  function fillPreview() {
185	    if (scripted) return;
186	    while (next.length < PREVIEW) next.push(randomType());
187	  }
188	
189	  function shapeCells(matrix, row, col) {
190	    var cells = [];
191	    for (var r = 0; r < matrix.length; r++) {
192	      for (var c = 0; c < matrix[r].length; c++) {
193	        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
194	      }
195	    }
196	    return cells;
197	  }
198	
199	  function fits(matrix, row, col) {
200	    var cells = shapeCells(matrix, row, col);
201	    for (var i = 0; i < cells.length; i++) {
202	      var r = cells[i][0], c = cells[i][1];
203	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
204	      if (board[r][c] !== "") return false;
205	    }
206	    return true;
207	  }
208	
209	  function spawn() {
210	    if (next.length === 0) scripted = false;
211	    fillPreview();
212	    var type = next.shift();
213	    fillPreview();
214	    var s = SHAPES[type];
215	    var piece = { type: type, matrix: s.m.slice(), row: s.row, col: s.col };
216	    if (!fits(piece.matrix, piece.row, piece.col)) {
217	      current = null;
218	      status = "over";
219	      stopTimer();
220	      return;
221	    }
222	    current = piece;
223	  }
224	
225	  function lock() {
226	    var cells = shapeCells(current.matrix, current.row, current.col);
227	    for (var i = 0; i < cells.length; i++) {
228	      board[cells[i][0]][cells[i][1]] = current.type;
229	    }
230	    current = null;
231	    spawn();
232	  }
233	
234	  function tryMove(dr, dc) {
235	    if (!current) return false;
236	    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
237	    current.row += dr;
238	    current.col += dc;
239	    return true;
240	  }
241	
242	  // The single gravity step, used by both the real timer and tick().
243	  function gravityStep() {
244	    if (status !== "running" || !current) return;
245	    if (!tryMove(1, 0)) lock();
246	  }
247	
248	  function rotate() {
249	    if (!current) return;
250	    var m = current.matrix;
251	    var n = m.length;
252	    var rotated = [];
253	    for (var r = 0; r < n; r++) {
254	      var line = "";
255	      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
256	      rotated.push(line);
257	    }
258	    var kicks = [[0, 0], [0, -1], [0, 1], [0, -2], [0, 2], [1, 0]];
259	    for (var i = 0; i < kicks.length; i++) {
260	      var nr = current.row + kicks[i][0];
261	      var nc = current.col + kicks[i][1];
262	      if (fits(rotated, nr, nc)) {
263	        current.matrix = rotated;
264	        current.row = nr;
265	        current.col = nc;
266	        return;
267	      }
268	    }
269	  }
270	
271	  function hardDrop() {
272	    if (!current) return;
273	    while (tryMove(1, 0)) {}
274	    lock();
275	  }
276	
277	  function applyInput(action) {
278	    if (status !== "running" || !current) return;
279	    switch (action) {
280	      case "left": tryMove(0, -1); break;
281	      case "right": tryMove(0, 1); break;
282	      case "softDrop": gravityStep(); break;
283	      case "hardDrop": hardDrop(); break;
284	      case "rotate": rotate(); break;
285	    }
286	  }
287	
288	  // ---- Timer ----
289	  function stopTimer() {
290	    if (timer !== null) { clearInterval(timer); timer = null; }
291	  }
292	
293	  function startTimer() {
294	    stopTimer();
295	    timer = setInterval(function () {
296	      gravityStep();
297	      render();
298	    }, GRAVITY_MS);
299	  }
300	
301	  // ---- Rendering (synchronous) ----
302	  var boardEl = document.getElementById("board");
303	  var nextEl = document.getElementById("next");
304	  var overlayEl = document.getElementById("overlay");
305	  var scoreEl = document.getElementById("score");
306	  var levelEl = document.getElementById("level");
307	  var linesEl = document.getElementById("lines");
308	  var cellEls = [];
309	
310	  (function buildBoard() {
311	    for (var r = 0; r < ROWS; r++) {
312	      cellEls.push([]);
313	      for (var c = 0; c < COLS; c++) {
314	        var el = document.createElement("div");
315	        el.className = "cell";
316	        el.setAttribute("data-testid", "cell");
317	        el.setAttribute("data-row", String(r));
318	        el.setAttribute("data-col", String(c));
319	        el.setAttribute("data-filled", "false");
320	        el.setAttribute("data-piece", "");
321	        boardEl.appendChild(el);
322	        cellEls[r].push(el);
323	      }
324	    }
325	  })();
326	
327	  function paintCell(el, piece) {
328	    el.className = piece ? "cell p-" + piece : "cell";
329	    el.setAttribute("data-filled", piece ? "true" : "false");
330	    el.setAttribute("data-piece", piece);
331	  }
332	
333	  function renderNext() {
334	    nextEl.textContent = "";
335	    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
336	      var type = next[i];
337	      var m = SHAPES[type].m;
338	      var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
339	      var mini = document.createElement("div");
340	      mini.className = "mini";
341	      for (var r = 0; r < 2; r++) {
342	        for (var c = 0; c < 4; c++) {
343	          var ch = m[r + offset] && m[r + offset][c];
344	          var cell = document.createElement("div");
345	          cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
346	          mini.appendChild(cell);
347	        }
348	      }
349	      nextEl.appendChild(mini);
350	    }
351	  }
352	
353	  function render() {
354	    var view = board.map(function (row) { return row.slice(); });
355	    if (current) {
356	      var cells = shapeCells(current.matrix, current.row, current.col);
357	      for (var i = 0; i < cells.length; i++) {
358	        view[cells[i][0]][cells[i][1]] = current.type;
359	      }
360	    }
361	    for (var r = 0; r < ROWS; r++) {
362	      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c]);
363	    }
364	    scoreEl.textContent = String(score);
365	    levelEl.textContent = String(level);
366	    linesEl.textContent = String(lines);
367	    overlayEl.hidden = status !== "over";
368	    renderNext();
369	  }
370	
371	  // ---- Game control ----
372	  function validTypes(queue) {
373	    if (!Array.isArray(queue)) return [];
374	    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
375	  }
376	
377	  function newGame(queue) {
378	    board = emptyBoard();
379	    score = 0;
380	    level = 1;
381	    lines = 0;
382	    status = "running";
383	    current = null;
384	    bag = [];
385	    if (Array.isArray(queue)) {
386	      next = validTypes(queue);
387	      scripted = true;
388	    } else {
389	      next = [];
390	      scripted = false;
391	    }
392	    spawn();
393	    startTimer();
394	    render();
395	  }
396	
397	  function setQueue(queue) {
398	    next = validTypes(queue);
399	    scripted = true;
400	    render();
401	  }
402	
403	  function setBoard(rows) {
404	    var b = emptyBoard();
405	    for (var r = 0; r < ROWS; r++) {
406	      var line = (rows && rows[r]) || "";
407	      for (var c = 0; c < COLS; c++) {
408	        var ch = line.charAt(c);
409	        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
410	      }
411	    }
412	    board = b;
413	    render();
414	  }
415	
416	  function getBoard() {
417	    return board.map(function (row) {
418	      return row.map(function (v) { return v || "."; }).join("");
419	    });
420	  }
421	
422	  function getState() {
423	    var cur = null;
424	    if (current) {
425	      var cells = shapeCells(current.matrix, current.row, current.col);
426	      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
427	      cur = { type: current.type, cells: cells };
428	    }
429	    return {
430	      current: cur,
431	      next: next.slice(),
432	      score: score,
433	      level: level,
434	      lines: lines,
435	      status: status
436	    };
437	  }
438	
439	  function tick(n) {
440	    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
441	    for (var i = 0; i < steps; i++) gravityStep();
442	    render();
443	  }
444	
445	  window.__tetris = {
446	    newGame: newGame,
447	    setQueue: setQueue,
448	    setBoard: setBoard,
449	    tick: tick,
450	    input: function (action) { applyInput(action); render(); },
451	    getBoard: getBoard,
452	    getState: getState
453	  };
454	
455	  // ---- Keyboard ----
456	  var KEYS = {
457	    ArrowLeft: "left",
458	    ArrowRight: "right",
459	    ArrowDown: "softDrop",
460	    " ": "hardDrop",
461	    ArrowUp: "rotate"
462	  };
463	
464	  document.addEventListener("keydown", function (e) {
465	    var action = KEYS[e.key];
466	    if (!action) return;
467	    e.preventDefault();
468	    window.__tetris.input(action);
469	  });
470	
471	  document.getElementById("new-game").addEventListener("click", function (e) {
472	    e.currentTarget.blur();
473	    newGame();
474	  });
475	
476	  newGame();
477	})();
478	</script>
479	</body>
480	</html>
