  function gravityStep() {
    if (status !== "running" || !current) return;
    if (tryMove(1, 0)) {
      current.lockTicks = 0;
      return;
    }
    current.lockTicks++;
    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
  }

  // Left/right. A move made while the lock delay is running restarts it,
  // up to MAX_LOCK_RESETS times per piece.
  function shift(dc) {
    var resting = current.lockTicks > 0;
    if (!tryMove(0, dc)) return;
    if (resting && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets++;
      current.lockTicks = 0;
    }
  }

  // Clockwise rotation. Tries the rotated shape in place, then shifted
  // sideways; if none fit, the piece is left unchanged.
  function rotateCW() {''')
rep('''    var kicks = [[0, 0], [0, -1], [0, 1], [0, -2], [0, 2], [1, 0]];
    for (var i = 0; i < kicks.length; i++) {
