        current.matrix = rotated;
        current.col = nc;
        return;
      }
    }''')
rep('''  function hardDrop() {''','''  // Hard drop skips the lock delay.
  function hardDrop() {''')
rep('''      case "left": tryMove(0, -1); break;
      case "right": tryMove(0, 1); break;''','''      case "left": shift(-1); break;
      case "right": shift(1); break;''')
rep('''      case "rotate": rotate(); break;''','''      case "rotateCW":
      case "rotate": rotateCW(); break;''')
rep('''    ArrowUp: "rotate"''','''    ArrowUp: "rotateCW"''')
