const fs=require('fs'),assert=require('assert');
const html=fs.readFileSync('/Users/vmysla/src/ab-study/arms/tetris-rep-control-01/control/index.html','utf8');
const src=html.match(/<script>([\s\S]*)<\/script>/)[1];
function el(){return {setAttribute(){},appendChild(){},addEventListener(){},set textContent(v){},hidden:false,className:''};}
global.window={}; global.document={getElementById:el,createElement:el,addEventListener(){}};
global.setInterval=()=>1; global.clearInterval=()=>{};
eval(src);
const T=window.__tetris, cells=()=>JSON.stringify(T.getState().current&&T.getState().current.cells);
const E='..........';
// Rotation works via rotateCW
T.newGame(['T','O','O','O']); T.tick(2);
let before=cells(); T.input('rotateCW'); assert.notStrictEqual(cells(),before);
assert.deepStrictEqual(T.getState().current.cells,[[2,4],[3,4],[3,5],[4,4]]);
// Refused rotation leaves piece unchanged: I horizontal in a 1-row slot
T.newGame(['I','O']);
let rows=Array(20).fill(E); rows[0]='TTT....TTT'; rows[2]='TTTTTTTTTT'; rows[3]='TTTTTTTTTT'; T.setBoard(rows);
T.newGame(['I','O']); T.setBoard(rows); // spawn on empty then setBoard
before=cells(); T.input('rotateCW'); assert.strictEqual(cells(),before,'refused rotation');
// Sideways kick at wall: vertical I at right edge rotating back
T.newGame(['I','O']); T.input('rotateCW'); for(let i=0;i<6;i++)T.input('right');
let c=T.getState().current.cells; assert(c.every(x=>x[1]===9));
T.input('rotateCW'); c=T.getState().current.cells; assert(c.every(x=>x[1]>=0&&x[1]<=9)&&new Set(c.map(x=>x[0])).size===1,'kicked');
// Lock delay: 2 ticks
T.newGame(['O','T','T']); T.tick(18); // O at rows 18-19
assert.strictEqual(T.getState().current.type,'O');
T.tick(1); assert.strictEqual(T.getState().current.type,'O','1st tick no lock');
T.tick(1); assert.strictEqual(T.getState().current.type,'T','locks on 2nd tick');
// Resets: max 3
T.newGame(['O','T','T']); T.tick(18);
for(let k=0;k<3;k++){ T.tick(1); T.input(k%2?'right':'left'); assert.strictEqual(T.getState().current.type,'O'); }
T.tick(1); T.input('left'); // 4th move: no restart
T.tick(1); assert.strictEqual(T.getState().current.type,'T','locks after cap');
// Without cap exhausted, move restarts
T.newGame(['O','T','T']); T.tick(18); T.tick(1); T.input('left'); T.tick(1); assert.strictEqual(T.getState().current.type,'O');
// Count persists across falls: step ledge
T.newGame(['O','T','T']);
